import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788283445000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>All configuration is by environment variable; there is no config file.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>LINKWARDEN_URL</code></td><td>yes</td><td>string</td><td>—</td><td>Base URL, e.g. <code>https://links.example.net</code>. Without <code>/api/v1</code>.</td></tr><tr><td><code>LINKWARDEN_TOKEN</code></td><td>yes</td><td>secret</td><td>—</td><td>Access token from Settings → Access Tokens.</td></tr><tr><td><code>LINKWARDEN_READ_ONLY</code></td><td>no</td><td>boolean</td><td><code>false</code></td><td><code>true</code> registers only the 11 read tools.</td></tr><tr><td><code>LINKWARDEN_ALLOW_TOOLS</code></td><td>no</td><td>string</td><td>—</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register.</td></tr><tr><td><code>LINKWARDEN_DENY_TOOLS</code></td><td>no</td><td>string</td><td>—</td><td>Same syntax; subtracted from whatever the allow list left.</td></tr><tr><td><code>LINKWARDEN_INSECURE_TLS</code></td><td>no</td><td>boolean</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, scoped to this connection.</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td>boolean</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed.</strong></td></tr></tbody></table><p>Booleans are compared against the literal string <code>true</code>. <code>True</code>, <code>1</code> and <code>yes</code> are off, so a typo fails closed rather than silently disabling certificate validation.</p><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><p><code>LINKWARDEN_ALLOW_TOOLS</code> and <code>LINKWARDEN_DENY_TOOLS</code> are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Registers</th></tr></thead><tbody><tr><td><code>essential</code></td><td>the curated eight, marked in the <a href="/reference/tools">tool reference</a></td></tr><tr><td><code>search_links,get_link</code></td><td>exactly those two</td></tr><tr><td><code>list_*</code></td><td><code>list_collections</code>, <code>list_rss_subscriptions</code>, <code>list_tags</code></td></tr><tr><td><code>essential,get_dashboard</code></td><td>the preset plus one more</td></tr><tr><td><code>*</code></td><td>everything — the same as leaving it unset</td></tr></tbody></table><p>Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>LINKWARDEN_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_link</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>LINKWARDEN_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p><h2 id="validation-at-startup" tabindex="-1">Validation at startup <a class="header-anchor" href="#validation-at-startup" aria-label="Permalink to “Validation at startup”">​</a></h2><p><code>LINKWARDEN_URL</code> is parsed with <code>new URL</code>. The server <strong>exits</strong> when it:</p><ul><li>does not parse,</li><li>uses a scheme other than <code>http:</code> or <code>https:</code>,</li><li>contains credentials (<code>https://user:pw@host</code>).</li></ul><p>It <strong>warns and continues</strong> when:</p><ul><li>the URL is plain <code>http:</code> to a non-loopback host (the token would be sent in clear),</li><li><code>LINKWARDEN_TOKEN</code> does not start with <code>ey</code> (Linkwarden tokens are NextAuth JWTs, so this usually means a cookie or password was pasted in),</li><li>either required variable is missing — the server still starts and lists its tools so registries and inspectors can introspect it; every call then fails with setup instructions.</li></ul><p>Normalisation: a trailing slash is stripped, and a <code>/api/v1</code> suffix is removed, since the client appends the prefix itself and redirects are never followed.</p><h2 id="token-handling" tabindex="-1">Token handling <a class="header-anchor" href="#token-handling" aria-label="Permalink to “Token handling”">​</a></h2><p><code>LINKWARDEN_TOKEN</code> is <strong>deleted from the process environment</strong> as soon as it is read — before any branch of the parser, including the ones that exit — so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code>. It is never logged and never appears in an error message.</p><h2 id="not-environment-variables" tabindex="-1">Not environment variables <a class="header-anchor" href="#not-environment-variables" aria-label="Permalink to “Not environment variables”">​</a></h2><p>There are no variables for timeouts, page sizes or result budgets; those are fixed:</p><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th></tr></thead><tbody><tr><td>Request timeout</td><td>30 s</td></tr><tr><td>Response body ceiling</td><td>8 MB</td></tr><tr><td>Result budget</td><td>200 000 characters</td></tr><tr><td>Links per search</td><td>100</td></tr><tr><td>Links per bulk operation</td><td>200</td></tr><tr><td>Article slice, default</td><td>20 000 characters</td></tr><tr><td>Confirmation token TTL</td><td>5 minutes</td></tr></tbody></table><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Where the <code>LINKWARDEN_*</code> booleans fail <em>off</em> on a typo, this one stops the server with exit code 1. It is the only variable here that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em><code>LINKWARDEN_TOKEN</code> is deleted from <code>process.env</code>, so the fatal path cannot leave the token sitting there for a crash reporter.</p>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};